# TCP/IP Server in C

Here's a complete TCP/IP server implementation in C:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>

#define PORT        8080
#define BUFFER_SIZE 1024
#define MAX_CLIENTS 10
#define BACKLOG     5

/* Global server socket for cleanup */
int server_fd = -1;

/* Signal handler for graceful shutdown */
void handle_signal(int signal) {
    printf("\n[Server] Caught signal %d. Shutting down...\n", signal);
    if (server_fd != -1) {
        close(server_fd);
    }
    exit(0);
}

/* Handle communication with a connected client */
void handle_client(int client_fd, struct sockaddr_in client_addr) {
    char buffer[BUFFER_SIZE];
    char client_ip[INET_ADDRSTRLEN];
    int bytes_received;

    /* Convert client IP to string */
    inet_ntop(AF_INET, &client_addr.sin_addr, client_ip, INET_ADDRSTRLEN);
    printf("[Server] Client connected: %s:%d\n",
           client_ip, ntohs(client_addr.sin_port));

    while (1) {
        /* Clear buffer */
        memset(buffer, 0, BUFFER_SIZE);

        /* Receive data from client */
        bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);

        if (bytes_received < 0) {
            perror("[Server] recv() failed");
            break;
        } else if (bytes_received == 0) {
            printf("[Server] Client %s:%d disconnected.\n",
                   client_ip, ntohs(client_addr.sin_port));
            break;
        }

        printf("[Client %s:%d] %s\n",
               client_ip, ntohs(client_addr.sin_port), buffer);

        /* Echo message back to client (or add custom logic here) */
        char response[BUFFER_SIZE + 64];
        snprintf(response, sizeof(response), "Server received: %s", buffer);

        if (send(client_fd, response, strlen(response), 0) < 0) {
            perror("[Server] send() failed");
            break;
        }

        /* Exit condition */
        if (strncmp(buffer, "exit", 4) == 0) {
            printf("[Server] Client %s:%d requested exit.\n",
                   client_ip, ntohs(client_addr.sin_port));
            break;
        }
    }

    close(client_fd);
    printf("[Server] Connection with %s:%d closed.\n",
           client_ip, ntohs(client_addr.sin_port));
}

int main(void) {
    int                client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t          client_len = sizeof(client_addr);
    int                opt        = 1;

    /* Register signal handlers */
    signal(SIGINT,  handle_signal);
    signal(SIGTERM, handle_signal);

    /* ── Step 1: Create socket ── */
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("[Server] socket() failed");
        exit(EXIT_FAILURE);
    }
    printf("[Server] Socket created successfully.\n");

    /* ── Step 2: Set socket options ── */
    if (setsockopt(server_fd, SOL_SOCKET,
                   SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt)) < 0) {
        perror("[Server] setsockopt() failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    /* ── Step 3: Bind socket to address/port ── */
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family      = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;   /* Listen on all interfaces */
    server_addr.sin_port        = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr,
             sizeof(server_addr)) < 0) {
        perror("[Server] bind() failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("[Server] Socket bound to port %d.\n", PORT);

    /* ── Step 4: Listen for connections ── */
    if (listen(server_fd, BACKLOG) < 0) {
        perror("[Server] listen() failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }
    printf("[Server] Listening on port %d...\n", PORT);

    /* ── Step 5: Accept and handle clients ── */
    while (1) {
        printf("[Server] Waiting for a connection...\n");

        client_fd = accept(server_fd,
                           (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR) {
                /* Interrupted by signal — exit gracefully */
                break;
            }
            perror("[Server] accept() failed");
            continue;
        }

        /* Fork a child process to handle the client */
        pid_t pid = fork();

        if (pid < 0) {
            perror("[Server] fork() failed");
            close(client_fd);
        } else if (pid == 0) {
            /* ── Child process ── */
            close(server_fd);               /* Child doesn't need server fd */
            handle_client(client_fd, client_addr);
            exit(EXIT_SUCCESS);
        } else {
            /* ── Parent process ── */
            close(client_fd);              /* Parent doesn't need client fd */
        }
    }

    close(server_fd);
    return 0;
}
```

---

## How to Compile & Run

```bash
# Compile
gcc -Wall -Wextra -o tcp_server tcp_server.c

# Run
./tcp_server
```

## Test with `telnet` or `nc`

```bash
# Using netcat
nc localhost 8080

# Using telnet
telnet localhost 8080
```

---

## Program Flow

```
socket()  →  setsockopt()  →  bind()  →  listen()  →  accept()
                                                           │
                                                        fork()
                                                       /      \
                                                  Parent      Child
                                              (next client) (handle_client)
```

---

## Key Functions Explained

| Function | Purpose |
|----------|---------|
| `socket()` | Creates a TCP socket (`SOCK_STREAM`) |
| `setsockopt()` | Allows reuse of address/port after restart |
| `bind()` | Assigns IP address and port to socket |
| `listen()` | Marks socket as passive (ready to accept) |
| `accept()` | Blocks until a client connects |
| `recv()` | Reads data from connected client |
| `send()` | Sends data to connected client |
| `fork()` | Creates child process per client |

---

## Possible Enhancements

- **Multi-threading** – Use `pthread` instead of `fork()`
- **Non-blocking I/O** – Use `select()`, `poll()`, or `epoll()`
- **TLS/SSL** – Add encryption with OpenSSL
- **Protocol parsing** – Handle HTTP or custom protocols
- **Connection pool** – Limit and manage concurrent clients

